package pi.kit.mob.env

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * The rules that decide which paths an app update replaces.
 *
 * Pinned on the JVM because they run before anything is deleted: the manifest
 * the content archive carries *is* the deletion list, so a root the parser
 * accepts wrongly — a traversal, or one root inside another — is a path removed
 * from a live environment on the next launch. The archive split is pinned for
 * the opposite reason: a content archive folded into the seed would never be
 * updated again, and nothing about the result would look broken.
 */
class ContentLayerTest {

    @Test
    fun `a manifest parses to its roots, comments and blanks skipped`() {
        val manifest = """
            # Generated by tools/build-runtime-image.py.
            bin/pi

            share/pikit
            libexec/pikit
        """.trimIndent()
        assertEquals(
            listOf("bin/pi", "share/pikit", "libexec/pikit"),
            parseContentRoots(manifest),
        )
    }

    @Test
    fun `declared order survives the parse`() {
        // The installer replaces roots in the order the manifest names them;
        // sorting is the builder's and the nesting check's business.
        assertEquals(
            listOf("share/pikit", "bin/pi"),
            parseContentRoots("share/pikit\nbin/pi\n"),
        )
    }

    @Test
    fun `a traversal is refused before anything is deleted`() {
        for (root in listOf("..", "bin/../../etc", "/bin/pi", "bin/./pi", "bin/pi/")) {
            assertThrows(IllegalStateException::class.java) {
                parseContentRoots("$root\n")
            }
        }
    }

    @Test
    fun `roots that nest are refused`() {
        assertThrows(IllegalStateException::class.java) {
            parseContentRoots("lib/node_modules\nlib/node_modules/pikit-extensions\n")
        }
    }

    @Test
    fun `an empty manifest is refused`() {
        assertThrows(IllegalStateException::class.java) {
            parseContentRoots("# nothing but a comment\n\n")
        }
    }

    @Test
    fun `the content archive is split out of the listing`() {
        val split = splitArchiveNames(
            listOf("revision.txt", "overlay.zip", "bootstrap.zip", "content.zip", "content-revision.txt"),
        )
        assertEquals(listOf("bootstrap.zip", "overlay.zip"), split.seed)
        assertEquals("content.zip", split.content)
    }

    @Test
    fun `the content archive is matched by name, not by order`() {
        // Sorted, so the seed list is stable whatever order `assets.list` uses,
        // and the content archive is named — a third seed zip would be unpacked
        // with the seed and never point-replaced.
        val split = splitArchiveNames(listOf("z.zip", "a.zip", "content.zip", "m.zip"))
        assertEquals(listOf("a.zip", "m.zip", "z.zip"), split.seed)
        assertEquals("content.zip", split.content)
    }

    @Test
    fun `an image without a content layer has none`() {
        val split = splitArchiveNames(listOf("bootstrap.zip", "overlay.zip", "revision.txt"))
        assertEquals(listOf("bootstrap.zip", "overlay.zip"), split.seed)
        assertNull(split.content)
    }

    @Test
    fun `non-archive entries are ignored`() {
        val split = splitArchiveNames(listOf("revision.txt", "build-metadata.json", "content.zip"))
        assertEquals(emptyList<String>(), split.seed)
        assertEquals("content.zip", split.content)
    }
}
